<div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?php echo h($user['name']); ?></td><td><?php echo h($user['email']); ?></td><td><?php echo h($user['role']); ?></td><td><?php echo h($user['created_at']); ?></td><td><?php if ($user['role'] === 'user'): ?><form method="post"><input type="hidden" name="action" value="delete_user"><input type="hidden" name="id" value="<?php echo $user['id']; ?>"><button class="danger" type="submit">Remove</button></form><?php else: ?>Protected<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
